import sys


def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    money = int(next(it)) // 10  # 预算除以 10
    m = int(next(it))

    items = [None] * (m + 1)          # items[i] = (价格/10, 价值)
    main_idx = []                      # 主件编号
    attachments = {}                  # 主件 -> 附件列表

    for i in range(1, m + 1):
        v, p, q = int(next(it)), int(next(it)), int(next(it))
        items[i] = (v // 10, v * p)
        if q == 0:
            main_idx.append(i)
            attachments[i] = []
        else:
            attachments.setdefault(q, []).append(i)

    groups = []
    for mi in main_idx:
        v0, val0 = items[mi]
        atts = attachments[mi]
        combos = [(v0, val0)]  # 只买主件
        for mask in range(1, 1 << len(atts)):  # 附件子集
            w, value = v0, val0
            for k, ai in enumerate(atts):
                if mask >> k & 1:
                    w += items[ai][0]
                    value += items[ai][1]
            combos.append((w, value))
        groups.append(combos)

    dp = [0] * (money + 1)
    for combos in groups:
        for j in range(money, -1, -1):
            for w, value in combos:
                if j >= w:
                    dp[j] = max(dp[j], dp[j - w] + value)

    print(dp[money])


if __name__ == "__main__":
    solve()
